insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 1, 'Identify the type of text.', 'Technology has changed the way people communicate. Today, individuals can connect with others across the world within seconds through digital platforms. This has made communication faster, easier, and more accessible.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 2, 'Identify the type of text.', 'I was planning to wake up early today, but my alarm rang and I just looked at it for five minutes before sleeping again. Somehow I still managed to reach college on time.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 3, 'Identify the type of text.', 'Reading books is a valuable habit that improves vocabulary, enhances imagination, and develops critical thinking. It also provides an opportunity to explore different perspectives and gain knowledge about the world.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 4, 'Identify the type of text.', 'I tried making coffee without checking the instructions. Added too much sugar, forgot the milk, and somehow ended up making something that tasted like sweet water.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 5, 'Identify the type of text.', 'Artificial Intelligence is transforming various industries by improving efficiency, automating repetitive tasks, and supporting data-driven decision-making. Its applications continue to expand across healthcare, education, transportation, and business.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 6, 'Identify the type of text.', 'Yesterday my friend borrowed my headphones and returned them with one side not working. He said they were already like that. Funny thing is, both sides worked perfectly before he took them.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 7, 'Identify the type of text.', 'Healthy eating plays an important role in maintaining overall well-being. A balanced diet containing fruits, vegetables, proteins, and whole grains helps the body receive essential nutrients and maintain energy levels.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 8, 'Identify the type of text.', 'I went to buy just one thing from the supermarket and came back with three bags. I don''t even remember buying half of it. Shopping is dangerous when you''re hungry.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 9, 'Identify the type of text.', 'Climate change is one of the major environmental challenges facing the world today. Rising temperatures, changing weather patterns, and melting glaciers highlight the importance of adopting sustainable practices.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 10, 'Identify the type of text.', 'I started watching a series because my friend said it had only a few episodes. Now it''s 3 AM, I''ve finished two seasons, and I have absolutely no regrets. Okay, maybe a little.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 11, 'Identify the type of text.', 'Online education has created new opportunities for learners by providing flexible access to courses and educational resources. Students can learn at their own pace and explore subjects beyond traditional classroom boundaries.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 12, 'Identify the type of text.', 'My little cousin asked me how the internet works. I started explaining routers and servers, but halfway through I realised I was confusing myself more than him.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 13, 'Identify the type of text.', 'Space exploration allows scientists to understand the universe, study distant planets, and investigate the possibility of life beyond Earth. These discoveries also contribute to technological advancements on our own planet.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 14, 'Identify the type of text.', 'I thought I had lost my wallet yesterday. Checked my bag, searched the whole room, even called my friend. Turns out I was holding it in my hand the entire time.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'B');
insert into questions (round_number, position, prompt, body, options, correct_option) values (3, 15, 'Identify the type of text.', 'Cybersecurity is essential in today''s digital environment. Strong passwords, regular software updates, and awareness of suspicious links can help individuals and organizations protect their information from potential threats.', '[{"key":"A","label":"AI-Generated Text"},{"key":"B","label":"Human-Written Text"},{"key":"C","label":"Mixed Text (Partly AI-Generated and Partly Human-Written)"}]'::jsonb, 'A');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 1, 'The Mystery Hand', 'Image 1, top row, first panel', 'Which clue should make you investigate further?', 'A person is holding a coffee mug. Something about the hand looks unusual.', '[{"key":"A","label":"The person''s clothing colour"},{"key":"B","label":"The hand appears to have an extra finger"},{"key":"C","label":"The background is blurred"},{"key":"D","label":"The photograph has warm lighting"}]'::jsonb, 'B');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 2, 'The Impossible Reflection', 'Image 2, top row, second panel', 'What is the strongest suspicious clue?', 'A woman is standing in front of a mirror. Her reflection appears to behave differently.', '[{"key":"A","label":"The mirror has a golden frame"},{"key":"B","label":"The room has warm lighting"},{"key":"C","label":"The reflection shows a different hand position"},{"key":"D","label":"The woman is wearing a blue shirt"}]'::jsonb, 'C');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 3, 'The Broken Clock', 'Image 3, top row, third panel', 'What is the suspicious detail?', 'A wall clock appears normal at first glance, but something is wrong with its mechanism.', '[{"key":"A","label":"The clock has Roman-style surroundings"},{"key":"B","label":"The clock has three hands instead of two"},{"key":"C","label":"The clock is circular"},{"key":"D","label":"The wall is white"}]'::jsonb, 'B');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 4, 'The Bicycle Mystery', 'Image 4, top row, fourth panel', 'Which detail appears physically inconsistent?', 'A bicycle is parked outside. Look carefully at its mechanical components.', '[{"key":"A","label":"The bicycle has a blue frame"},{"key":"B","label":"The rear wheel is large"},{"key":"C","label":"The chain appears incorrectly connected to the gears"},{"key":"D","label":"The bicycle has two pedals"}]'::jsonb, 'C');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 5, 'The Suspicious Fork', 'Image 5, top row, fifth panel', 'What should a detective inspect most carefully?', 'A dining table has a glass, a plate and a fork.', '[{"key":"A","label":"The colour of the table"},{"key":"B","label":"The number and shape of the fork''s prongs"},{"key":"C","label":"The position of the glass"},{"key":"D","label":"The food on the plate"}]'::jsonb, 'B');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 6, 'The Traffic Light Glitch', 'Image 6, bottom row, first panel', 'What makes this image suspicious?', 'A traffic signal is displaying something unusual.', '[{"key":"A","label":"The traffic signal is mounted on a pole"},{"key":"B","label":"The background contains buildings"},{"key":"C","label":"Both red and green lights are illuminated simultaneously"},{"key":"D","label":"The sky is blue"}]'::jsonb, 'C');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 7, 'The Eyes Don''t Lie', 'Image 7, bottom row, second panel', 'What is the suspicious clue?', 'A person is wearing sunglasses. The reflections in the lenses deserve a closer look.', '[{"key":"A","label":"The glasses have a black frame"},{"key":"B","label":"The reflections in the two lenses show inconsistent surroundings"},{"key":"C","label":"The person has curly hair"},{"key":"D","label":"The photograph is a close-up"}]'::jsonb, 'B');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 8, 'The Impossible Staircase', 'Image 8, bottom row, third panel', 'What should you investigate?', 'A staircase appears inside a house. Something about its construction seems impossible.', '[{"key":"A","label":"The staircase has wooden steps"},{"key":"B","label":"The staircase appears to lead into an impossible ceiling structure"},{"key":"C","label":"The walls are beige"},{"key":"D","label":"There is a plant beside the staircase"}]'::jsonb, 'B');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 9, 'The Library of Lies', 'Image 9, bottom row, fourth panel', 'What is the strongest indication of AI-generated content?', 'A bookshelf contains several books. Look closely at their printed titles.', '[{"key":"A","label":"The books have different colours"},{"key":"B","label":"The books are arranged vertically"},{"key":"C","label":"Several book titles contain distorted or nonsensical lettering"},{"key":"D","label":"The bookshelf is made of wood"}]'::jsonb, 'C');
insert into questions (round_number, position, title, hint, prompt, body, options, correct_option) values (4, 10, 'The Shadow Suspect', 'Image 10, bottom row, fifth panel', 'Which detail should be investigated?', 'A dog is standing outdoors in bright sunlight. A detective must examine the relationship between the subject and its shadow.', '[{"key":"A","label":"The dog''s fur colour"},{"key":"B","label":"The dog''s position on the pavement"},{"key":"C","label":"Whether the dog''s shadow aligns with the surrounding light direction"},{"key":"D","label":"The presence of outdoor furniture"}]'::jsonb, 'C');
