-- All the game's questions. Round 1 and 2 answers stay empty until the user sends them.
select 1, n, 'Image ' || n, 'Is it AI-generated or a real image?',
  '[{"key":"AI","label":"AI-generated"},{"key":"REAL","label":"Real"}]'::jsonb
from generate_series(1, 20) n;

select 2, n, 'Video ' || n, 'Is it AI-generated or a real video?',
  '[{"key":"AI","label":"AI-generated"},{"key":"REAL","label":"Real"}]'::jsonb
from generate_series(1, 10) n;

